package com.studysync.controller;
import com.studysync.dao.UserDAO; import com.studysync.model.User; import com.studysync.util.JsonUtil; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.*;
@WebServlet("/api/auth") public class AuthServlet extends HttpServlet { private UserDAO dao=new UserDAO(); protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{String action=req.getParameter("action");String email=req.getParameter("email");String password=req.getParameter("password");if("signup".equals(action)){User u=new User(0,req.getParameter("name"),email,password);if(dao.exists(email)){JsonUtil.send(res,"{\"ok\":false,\"message\":\"Email already exists\"}");return;}int id=dao.save(u);JsonUtil.send(res,"{\"ok\":true,\"id\":"+id+"}");}else{User u=dao.login(email,password);if(u==null)JsonUtil.send(res,"{\"ok\":false,\"message\":\"Invalid email or password\"}");else{req.getSession().setAttribute("user",u);JsonUtil.send(res,"{\"ok\":true,\"id\":"+u.getId()+",\"name\":\""+u.getName().replace("\"","\\\"")+"\"}");}}}catch(Exception e){JsonUtil.send(res,"{\"ok\":false,\"message\":\"Server error\"}");}}}
